function OverseaClubBossChallengeDialog:RefreshShow(questId)
    self:SetBg()
    self:SetBossNodeState()
    local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
    local bossInfo = bossDojo:GetBossInfo()
    for i, v in pairs(bossInfo) do
        local vo = ClubUtils.GetBossPassVo(v.questId)
        if next(vo) then
            v.vo = vo
        end
    end

    table.sort(bossInfo,function(a,b)
        if a.vo.bossTypes == b.vo.bossTypes then
            return a.vo.id < b.vo.id
        else
            return a.vo.bossTypes < b.vo.bossTypes
        end
    end)

    local index = self:GetPreIndex()
    for i, v in pairs(bossInfo) do
        if self.type == ClubUtils.BossType.NormalBoss then
            if v.vo.bossTypes == ClubUtils.BossType.NormalBoss then
                local preSelect
                if not isNull(index) then
                    preSelect = checkNumber(index)
                else
                    preSelect =  v.questId == self.questId and i or 0
                end
                if questId then
                    preSelect = v.questId == questId and i or 0
                end
                self.bossEnv[i]:RefreshBoss(v)
                self.bossEnv[i]:RefreshSelect(preSelect)
            end
        else
            if v.vo.bossTypes == ClubUtils.BossType.BigBoss then
                self:RefreshBossInfo(v)
            end
        end
    end
end
---这里要重新取一下Boss的Data 打完返回的时候 更新的数据 要刷新
function OverseaClubBossChallengeDialog:SetBg()
    local bgPath = self.type == ClubUtils.BossType.BigBoss and "Arts/Textures/UIBg/club_boss_bg_2.png" or "Arts/Textures/UIBg/club_boss_bg_1.png"
    CfUtils.FillImage(self.ImgBg,bgPath)
end

function OverseaClubBossChallengeDialog:GetPreIndex()
    local index
    if not isNull(self.controller) and not isNull(self.controller.Argument) then
        index = self.controller.Argument.extra
    end
    return index
end


function OverseaClubBossChallengeDialog:OnBossInfoNodeClick(i, data)
    if self.curIndex and self.curIndex == i then
        return
    end
    local lastIndex = self.curIndex
    if not isNull(lastIndex) then
        self.bossEnv[lastIndex]:DoSelect()
    end
    self.curIndex = i
    self.controller:SetExtraArgument(self.curIndex)
    self:RefreshBossInfo(data)
end

function OverseaClubBossChallengeDialog:SetBossNodeState()
    KTool.SetActive(self.RightPanel.gameObject,self.type == ClubUtils.BossType.NormalBoss)
end

function OverseaClubBossChallengeDialog:TopTabOnClickHandler(index)
