    self.curType = index
    self:RefreshRecord()
end

function OverseaClubBossChallengeDialog:OnBtnAllRecordClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIClubBossRecordDialog})
end

function OverseaClubBossChallengeDialog:OnBtnGoChallengeClick()
    if self.curBossData.remainingHp <= 0 then
        GameUtils.Toast(localize("当前讨伐已结束，请前往其他讨伐关卡"))
        return
    end

    local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
    if not bossDojo:IsHaveTimes() then
        GameUtils.Toast(localize("今日个人挑战次数已达上限"))
        return
    end

    if not bossDojo:IsCanEnter() then
        GameUtils.Toast(localize("当前社团今日特训次数已达上限"))
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self.curBossData.questId } }
    , {
                { id = Constants.UITypeIds.UIClubBossChallengeDialog },
            })
end

function OverseaClubBossChallengeDialog:OnBtnMonsterDetailsClick()
    if not isNull(self.curBossData) then
        if self.type == ClubUtils.BossType.NormalBoss then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIBossDetailDialog, parameters = { levelId = self.curBossData.questId } })
        else
            UIModule.OpenDialog({
                id = Constants.UITypeIds.UIClubBossDetailsDialog,parameters = { questId = self.curBossData.questId }
            })
        end
    end
end

function OverseaClubBossChallengeDialog:RefreshRecord()
    self.record = self.curType == 1 and self.curLogData.playerBossLog or self.curLogData.clubBossLog
    if self.ScrollView then
        if not self.ScrollView.IsListViewInit then
            self.ScrollView:InitListView(#self.record, Bind(self, self.OnRefreshCellIndex))
        else
            GameUtils.ReloadData(self.ScrollView, #self.record)
        end
    end
end

function OverseaClubBossChallengeDialog:RefreshBossInfo(data)
    self.curBossData = data
    self:SetTagAndNameByQuestId()
    CfUtils.SetUISwitchText(self.TextTitle,self.type == ClubUtils.BossType.NormalBoss and 1 or 2)
    CfUtils.FillText(self.HpNum,string.format("%s/%s",self.curBossData.remainingHp,self.curBossData.totalHp))
    self.HpSlider.value = self.curBossData.remainingHp/self.curBossData.totalHp

    local bossDojo  = ClubUtils.GetClubComp():GetBossDojo()
    local leaveTime = checkNumber(bossDojo:GetLeaveTimes())
    local totalTime = ClubUtils.GetClubComp():GetTotalChallengeTime()
    CfUtils.FillText(self.LeaveTimes,string.format("%s/%s",leaveTime,totalTime))
    self:RefreshBtnState()
    self:RequestBossLog()

    local isHaveNum = bossDojo:GetBossAtNumByQuestId(self.curBossData.questId)
    KTool.SetActive(self.InCombatNode.gameObject,isHaveNum > 0)
    if isHaveNum > 0 then
        CfUtils.FillText(self.CombatTitle,localize("_num_位社员挑战中",{_num_ = isHaveNum}))
    end
end

function OverseaClubBossChallengeDialog:RequestBossLog()
    GameUtils.Request(Interfaces.OverseaClubBossSingleBossRecord,{questId = self.curBossData.questId},function(request,response)
        if response.errCode == 0 then
            self.curLogData = response.data
            self:TopTabOnClickHandler(2)
        end
    end )
end

function OverseaClubBossChallengeDialog:RefreshBtnState()
    local bossDojo   = ClubUtils.GetClubComp():GetBossDojo()
    local haveCount  = bossDojo:IsHaveTimes()
    local isCanEnter = bossDojo:IsCanEnter()
    local isBossDie  = self.curBossData.remainingHp <= 0

    local style = "B1"
    if not haveCount or isBossDie or not isCanEnter then
        style = "B17"
    end

    self.BtnGoChallenge.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle(style)
end

function OverseaClubBossChallengeDialog:SetTagAndNameByQuestId()
    local bossData = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.curBossData.questId)
    for i, v in pairs(bossData) do
        for k, j in pairs(v.wave1NpcType) do
            if tonumber(j) == Constants.RoleClass.Boss then
                self.bossId = v.wave1NpcId[k]
                CfUtils.SetUISwitchImage(self.ImgAttribute,v.attribute[k])
            end
        end
    end

    if not isNull(self.bossId) then
        local monster = CardConfMgr:GetInstance():GetBaseMonstVo(self.bossId)
        if not isNull(monster) then
            self:RefreshMonsterImage(monster)
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(monster.skinId)
            if not isNull(skinVo) then
                CfUtils.FillText(self.BossName,skinVo.name)
            end
        end
    end
end



function OverseaClubBossChallengeDialog:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.record then
        return
    end

    local cell = listView:NewListViewItem(Cell)
    if not isNull(cell) then
        local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
        if not isNull(tableCellEnv) then
            tableCellEnv:RefreshShow(self.record[index + 1])
            tableCellEnv:SetCallBack(Bind(self,self.OnRecordCallBack))
        end
    end
    return cell
end

function OverseaClubBossChallengeDialog:OnRecordCallBack(obj,data)
    local excludeDialogs = {
        { id = Constants.UITypeIds.UIClubBossChallengeDialog },
    }
    GameUtils.ShowCommonTeamsTipsBoard(obj.gameObject, data.team, '', data.questId, data.playerName, excludeDialogs)
end

